ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["replies_ask_1"] = {
{"ASK_ADVICE","role=family_man|st=friendly,neutral,careful",{"Don't tell somebody you'll be there unless you mean it - they'll wait for you"}},
{"ASK_ADVICE","role=family_woman|st=friendly,neutral,careful",{"Watch who only comes around when they need something, you know the sort"}},
{"ASK_ADVICE","role=family_elder|st=friendly,neutral,careful",{"Don't wear yourself out finishing a job, leave enough in you to get back"}},
{"ASK_ADVICE","role=family_youth|st=friendly,neutral,careful",{"Ask, even if it sounds stupid, beats nodding along and fucking it up"}},
{"ASK_ADVICE","role=civilian_man|st=friendly,neutral,careful",{"Just because I sound sure doesn't mean I know - check for yourself too, alright?"},false,{[1]="GENERIC"}},
{"ASK_ADVICE","role=civilian_woman|st=friendly,neutral,careful",{"Try to remember what you actually saw, I scare myself worse afterward, filling in the gaps"}},
{"ASK_ADVICE","role=elite_operator|st=neutral,careful",{"Tell me what you saw, not what you reckon it means - start there"}},
{"ASK_ADVICE","role=elite_delta|st=neutral,careful",{"Can't confirm it? Don't stake your next move on it"}},
{"ASK_ADVICE","role=mercenary|st=neutral,careful",{"If they start rushing you when you ask questions, keep asking"}},
{"ASK_ADVICE","role=outlaw|st=neutral,careful",{"Find out what they want before you start trusting that smile"}},
{"ASK_ADVICE","role=raider|st=careful,hostile",{"Don't go around expecting fair, people see that and take advantage"}},
{"ASK_ADVICE","role=raider_boss|st=careful,hostile",{"Stop asking me if you're doing alright, work it out"}},
{"ASK_ADVICE","role=law_sheriff|st=friendly,neutral,careful",{"Keeping people safe and making them obey you aren't always the same thing - remember that if you're in charge"}},
{"ASK_ADVICE","role=law_officer|st=friendly,neutral,careful",{"If the story changes, ask why - don't help them make up a reason"}},
{"ASK_ADVICE","role=law_sergeant|st=friendly,neutral,careful",{"If somebody misunderstood you, sort it out now, before they go do something with it"}},
{"ASK_ADVICE","role=law_trooper|st=friendly,neutral,careful|world=road",{"Slow down for the bend, empty road behind you doesn't tell you what's past it"}},
{"ASK_ADVICE","role=law_corrections|st=friendly,neutral,careful",{"Tell people the rule and stick to it, don't wake up tomorrow and decide it's something different"}},
{"ASK_ADVICE","role=swat_lead|st=friendly,neutral,careful",{"If your plan needs every stranger to cooperate, change the plan"},false,false,{[1]={{t="Someone will panic - leave room for that",afterMs=1600}}}},
{"ASK_ADVICE","role=swat_operator|st=friendly,neutral,careful|world=door",{"Give the person watching the door some room, they might've seen something you haven't"}},
{"ASK_ADVICE","role=soldier|st=friendly,neutral,careful",{"If you didn't understand, say so - don't let people walk off thinking you did"}},
{"ASK_ADVICE","role=soldier_nco|st=friendly,neutral,careful",{"Check on each other when you're tired, you won't always notice yourself getting sloppy"}},
{"ASK_ADVICE","role=soldier_green|st=friendly,neutral,careful",{"Don't just nod if you didn't catch the order, I did that, wasn't worth saving the embarrassment"}},
{"ASK_ADVICE","role=deserter|st=friendly,neutral,careful",{"Think about waking up tomorrow with what you decided today - not just getting through this minute"}},
{"ASK_ADVICE","role=militia|st=friendly,neutral,careful",{"Having the equipment doesn't mean you know what you're doing - take it from me"}},
{"ASK_ADVICE","role=civilian_loner|st=friendly,neutral,careful",{"Don't get it in your head that alone means safe - nobody's there to tell you when you're being stupid"}},
{"ASK_ADVICE","role=worker|st=friendly,neutral,careful",{"Try the easy fix first, don't start tearing the whole thing apart"}},
{"ASK_ADVICE","role=rescue_firefighter|st=friendly,neutral,careful|world=door",{"Check how you'll get out BEFORE you go in, don't just assume that back door opens"}},
{"ASK_ADVICE","role=rescue_medical|st=friendly,neutral,careful",{"If somebody sounds reassuring, still ask if they actually know - including me"}},
{"ASK_ADVICE","role=rescue_clergy|st=friendly,neutral,careful",{"Sometimes you just have to sit and listen, you don't have to make the hurt go away in one sentence"}},
{"ASK_ADVICE","role=law_deputy|st=friendly,neutral,careful",{"Don't hurry just because somebody's yelling at you"},false,false,{[1]={{t="Yeah, easy for me to say... take a second, though, think it through",afterMs=1700}}}},
{"ASK_ADVICE","role=gang_member|st=neutral,careful",{"Don't act tough for people who'll leave you holding the bag"}},
{"ASK_ADVICE","role=gang_boss|st=neutral,careful,hostile",{"Make sure it's yours before you go promising someone a piece"}},
{"ASK_ADVICE","role=biker|st=neutral,careful",{"Patch tells you who he rides with - watch what he does before you trust him"}},
{"ASK_ADVICE","role=biker_boss|st=neutral,careful",{"Watch who sticks around when it's a pain in the ass - that's who you want"}},
{"ASK_ADVICE","role=crime_member|st=neutral,careful",{"Won't tell you what it costs? Don't take it yet"}},
{"ASK_ADVICE","role=prisoner|st=neutral,careful",{"Don't let somebody convince you you owe 'em just for leaving you alone"}},
{"ASK_ADVICE","role=family_man,family_woman,family_youth|tmp=fresh,seasoned|st=friendly,neutral",{"Keep the kids close, teach them to be quiet, that's all I've got","Never let them out of your sight, not for a minute"}},
{"ASK_ADVICE","role=family_elder|tmp=seasoned|st=friendly,neutral",{"I eat when there's food and sleep when it's quiet, and I don't trust a smile that comes easy","Don't burn yourself out the first week, honey, I've seen it happen"}},
{"ASK_ADVICE","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=friendly,neutral|hour=16,5|world=door",{"Always know where the back door is, and don't light a fire after dark"}},
{"ASK_ADVICE","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=friendly,neutral",{"Talk quieter, sound goes a long way out here"}},
{"ASK_ADVICE","role=civilian_loner|tmp=seasoned|st=friendly,neutral",{"Travel light - listen more than you talk - don't trust running water"}},
{"ASK_ADVICE","role=civilian_loner|tmp=seasoned|st=friendly,neutral|world=water,road",{"I like a route by the river, if there's a way through. Water doesn't make us invisible"}},
{"ASK_ADVICE","role=worker|tmp=seasoned|st=friendly,neutral",{"Know where your wrench is and where the nearest way out is","Work with someone, two people are safer than one with a plan"}},
{"ASK_ADVICE","role=rescue_firefighter|tmp=seasoned|st=friendly,neutral",{"Plan your exit before you plan your entry, the rest is detail","Don't go into a building you can't get out of - doesn't matter what's inside"}},
{"ASK_ADVICE","role=rescue_medical|tmp=seasoned|st=friendly,neutral",{"Wash every wound, if it swells, burns, or smells, find help fast","Sleep, water, food, in that order, you'll be no good to anyone without them"}},
{"ASK_ADVICE","role=rescue_clergy|tmp=seasoned|st=friendly,neutral",{"Hope takes work, every single day, like praying","Be kind, it costs little and buys more than you think"}},
{"ASK_ADVICE","role=law_deputy,law_officer|tmp=seasoned|st=friendly,neutral",{"Hands where I can see them, always, same rule for everyone","Walk, don't run, running draws attention - attention draws trouble"}},
{"ASK_ADVICE","role=law_sheriff,law_sergeant|tmp=veteran|st=friendly,neutral",{"Trust slowly and test often, that's the only way to stay alive","Keep a clear head, panic kills more people than any infected"}},
{"ASK_ADVICE","role=law_trooper|tmp=veteran|st=friendly,neutral|world=road",{"Don't ever park on an open road, I've seen what happens"}},
{"ASK_ADVICE","role=law_trooper|tmp=veteran|st=friendly,neutral",{"Know where the closest cover is at all times"}},
{"ASK_ADVICE","role=law_corrections|tmp=seasoned|st=friendly,neutral",{"Don't turn your back on anyone you haven't earned, in prison or out","Routines get people killed - change yours"}},
{"ASK_ADVICE","role=swat_lead,swat_operator|tmp=veteran|st=friendly,neutral",{"Slow is smooth, smooth is fast","Clear every corner before you enter it"}},
{"ASK_ADVICE","role=soldier,soldier_green|tmp=seasoned,fresh|st=friendly,neutral",{"Listen to your sergeant, they know more than you think","Don't be a hero, be the guy who comes home"}},
{"ASK_ADVICE","role=soldier_nco|tmp=veteran|st=friendly,neutral",{"Discipline, it's boring and it works","Cover your sector, don't get tunnel vision"}},
{"ASK_ADVICE","role=deserter,militia|tmp=seasoned|st=friendly,neutral",{"Trust nobody wearing a uniform, they'll turn on you","Never sit still, that's all I know"}},
{"ASK_ADVICE","role=elite_operator,elite_delta,mercenary|tmp=veteran|st=friendly,neutral",{"Quiet - always quiet, the loud ones die first","Know your exit - always"}},
{"ASK_ADVICE","role=outlaw|tmp=seasoned|st=friendly,neutral|world=road",{"Stay clear of the highway, stay clear of anyone with a badge, a bible, or a bad smile"}},
{"ASK_ADVICE","role=outlaw|tmp=seasoned|st=friendly,neutral",{"See everything, say nothing, that's what's kept me alive"}},
{"ASK_ADVICE","role=raider,raider_boss|tmp=predator|st=friendly,neutral",{"Hit first - hit hard, hit where they're weak","Never let them see you coming"}},
{"ASK_ADVICE","role=gang_member,gang_boss|tmp=predator|st=friendly,neutral",{"Know your set, know your enemy - don't ever sleep on either","Respect gets you farther than a gun"}},
{"ASK_ADVICE","role=biker,biker_boss|tmp=predator,veteran|st=friendly,neutral",{"Keep your bike tuned and your friends closer","Never ride alone - never"}},
{"ASK_ADVICE","role=crime_member|tmp=seasoned|st=friendly,neutral",{"Everything is negotiable - even survival","Don't make enemies - make arrangements"}},
{"ASK_ADVICE","role=prisoner|tmp=predator|st=friendly,neutral",{"Don't look 'em in the eye and don't stand still","Never trust a man who says he's your friend"}},
{"ASK_ADVICE","reg=law,swat|st=friendly,neutral|day=0,5",{"Head shots - every time, anything else just makes them angry","Don't get bitten, a scratch, a graze, anything breaking the skin, it's over","They aren't human - don't hesitate, don't apologize, fight for your life","Move quietly, stay inside - don't fire a gun unless you have to; it brings more","If one's close, back up - don't turn your back - aim high and hit hard","Never run in a straight line - put an obstacle between you and them","If you see someone sick, give them space - don't help - you can't","A bat in the head works, a knife works, a pillow doesn't"}},
{"ASK_ADVICE","reg=law,swat|st=friendly,neutral|day=0,5|world=door",{"Don't go into a house without checking the doors first - don't trust a silent house","Stay with a group, nobody sleeps alone - someone watches the door"}},
{"ASK_ADVICE","role=civilian_man,civilian_woman|tmp=fresh|st=friendly,neutral",{"Don't panic, I know, easier said, but if you panic you make noise, and noise gets you killed","Keep your shoes on, even when you sleep, you might have to run, and you can't run barefoot","Never go anywhere without telling someone, even if it's just yourself, out loud","Drink water before you're thirsty, eat before you're hungry, I learned that after I collapsed!","I don't know! Hide, mostly, I'm a lousy fighter!","Keep a bag packed by the door, flashlight, bandages, a Snickers if you got one","If someone's bleeding... stop the bleeding first, then run, I learned that from a lady at the church","Count your steps... count your breaths, count your cans, counting keeps you from screaming!","Trust your gut... if a place feels wrong -- it's wrong, leave"}},
{"ASK_ADVICE","role=civilian_man,civilian_woman|tmp=seasoned|st=friendly,neutral",{"Be boring, honestly, boring guys are the ones still here","Don't sleep out in the open and don't camp in one place too long","Wash your hands, and boil your water, and cover every cut, people forget the small things","Learn the sounds of the place, so the wrong sound stands out","Keep your tongue quiet and your boots laced... that's the only advice that's worked for me","Carry less than you think you need, you'll move faster, and speed saves lives","If you find a good group, stick with them, and if you find a bad one, run"}},
{"ASK_ADVICE","role=civilian_man,civilian_woman|st=friendly",{"You're doing fine, really, keep doing what you're doing, and don't be afraid to ask for help","My best advice? stay with people who make you laugh, even now, especially now!","Take a breath, you've got this, if you need me, I'm here"}},
{"ASK_ADVICE","role=civilian_man,civilian_woman|st=careful",{"Mind your own business, that's my advice","Don't ask strangers for advice, they might give it","Advice? get out of my sight, it's the safest thing for both of us"}},
{"ASK_ADVICE","role=civilian_loner",{"Move slow, think slower, shoot never if you can help it...","Never travel the same path twice, that's how they learn you","Sleep light, eat small, listen to the woods, they tell you everything","Trust nothing you can't see, and half of what you can","Water first, shelter second, food third, people last, the order saved my life","If you can't be quiet, be fast, if you can't be fast, be gone","Leave something behind when you go, a false trail, a decoy, it'll buy you an hour","Don't light a fire in a wind, don't sleep under a dead tree, learned both the hard way"}},
{"ASK_ADVICE","role=civilian_loner|st=careful",{"Advice is free, and I'm not giving it","Figure it out, I did","I don't give advice for free"}},
{"ASK_ADVICE","role=family_man,family_woman,family_elder,family_youth|st=friendly,neutral",{"Keep the kids busy, scared kids make noise, busy kids don't","Make a plan, write it down, and make everyone memorize it, even the little ones","Eat together, sleep together, stay together, we don't leave anyone behind","Pray, or whatever you do, do it, it helps, even if it's only for you","Ask for help, early, don't wait until you're desperate, desperate people make bad choices"}},
{"ASK_ADVICE","role=family_elder",{"Honey, I've outlived two wars and a flood, and I did it in good shoes","Keep your mouth shut, your ears open, and your pockets full of sugar","Don't be in a hurry to get anywhere, it'll come to you"}},
{"ASK_ADVICE","role=family_youth",{"Don't be stupid, I guess? like, don't go in the basement, don't split up, you know, the dumb stuff","Stay with someone older and smarter than you, they know things","Never trust a fence, a lock, or a nice guy"}},
{"ASK_ADVICE","role=worker",{"Respect the tools, respect the weather, respect the dead, in that order","Check twice, cut once, that applies to everything, doorframes, bandages, escape routes","Keep your hands busy, a busy hand is a calm hand","Know your exits, know your weapon, know your limits, and then know them again"}},
{"ASK_ADVICE","role=rescue_medical",{"Keep wounds clean, rest when you can, eat when you can, the body heals if you let it","If you get bitten, don't wait, don't hide it, tell someone, we can at least make it easier","Wash... boil, wrap, repeat, that's ninety percent of it...","Sleep, even when you can't, even if it's just ten minutes, your mind needs it"}},
{"ASK_ADVICE","role=rescue_clergy",{"Hold on to something, a faith, a person, a song, a memory, hold on tight","Be kind, even now, especially now, it costs little, and it returns more","Don't carry hate, it's heavier than any pack"}},
{"ASK_ADVICE","role=rescue_firefighter",{"Get low, know your way out, nothing in there's worth a second trip","Breathe first, then move, I've seen guys do it the other way around","Teamwork, always, you can't lift the beam alone"}},
{"ASK_ADVICE","role=militia",{"Keep that rifle clean and your head down, and don't run your mouth","Nobody sleeps without a watch posted, and nobody gets trusted on a handshake","Plan the retreat before you plan the attack"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=good,best",{"You asked, so listen, because I'm only saying this once, I want you to come back alive","I've got a good one for you, I picked it up the hard way, and I'm giving it to you, free","You're smart, you'll figure it out, but here's a shortcut I wish I'd had","For you, I've got a few, since you've been kind to everyone around here","My best one: never go anywhere without telling someone, even if it's only me","Keep a spare pair of socks in your coat, wet feet kill faster than you think, ha","Make friends, real ones, you've already started, keep going!","Take a real break, some food, a nap, somebody being nice to you","You're doing fine, really, don't second-guess yourself so much","Trust your instincts about people, yours are good","Stay in the habit of helping, it comes back, it always comes back","Know how to do something nobody else can and you'll always get fed","Keep your head, even when everyone else loses theirs, you can do it!!","Wish somebody had told me early, you can't save everybody, and it's not on you!!","Write things down, names, dates, places, memory fades","When in doubt, wait, patience has saved more lives than courage!","Eat before the shakes start, drink before your head hurts, I learned late","Be kind to yourself, you're carrying more than you admit","Don't take on a fight you can walk away from","Look after your feet, they'll look after you","Sing when you're alone, quietly, it keeps the dark from settling in","If you find a good person, hold on tight","Remember who you were, it helps you remember who you're still going to be!","Listen more than you speak, that's how you learn who to trust","Ask for help, early, I'll be here!","Keep one thing that's just for you, a photo, a song, a memory, don't trade it","Have a plan B, and a plan C, and a hiding place for each","Count your blessings, even the small ones, especially the small ones!","Share what you know, it makes you stronger, not weaker, ha","Mistakes happen, don't let them break you","Keep hoping, because folks like you give the rest of us a reason to"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=bad,worst",{"Advice for you? stop doing whatever it is you're doing!","I'd tell you to change your ways, but you won't"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=careful|rep=bad,worst",{"Get lost"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral|mood=fear",{"Run! no, hide! no- wait- ugh- I don't know, I'm terrible at this","Don't be like me, I panic at every sound, and it's exhausting","If something touches you, don't scream, if something chases you, don't stop","Steady hands, quiet voice... and please, please don't die on me","I'm no expert, I'm barely alive, but I'll tell you this, never turn your back","Pray, if you pray, and if you don't, start, it can't hurt"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral|mood=grim",{"Expect the worst, plan for the worst, and be surprised when it's only bad","Trust no one fully, and no one at all in the dark","Every day's a gift... a rotten one mostly, but I'll take it","Learn to eat what you hate, sleep where you can, and speak when you must","Don't take on more than you can carry, in your pack, or in your heart"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=sad",{"Tell the people you love that you love them... today, now, not tomorrow, tomorrow's a maybe","Hold on to the small things... a button, a photo, a song, they carry you..","Say sorry now, say thanks now... I waited too long on both"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=angry",{"Don't let anybody tell you what's safe, nobody knows, nobody has the right","Don't be a fool, don't be a hero, and for God's sake don't be nice to everyone","Make a plan, and then make a backup, and then curse the plan, and use the backup","Don't take orders from anyone who won't walk point"},false,false,{[4]={{t="I've buried a few who did!!",afterMs=3500}}}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly|mood=warm",{"You're doing great, you really are, keep going, I'm proud of you","Hang onto the good ones, there's not many left","Smile when you can, even if it's small, even if it hurts, it keeps you human"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=funny",{"Never trust a quiet house... a friendly stranger, or my cooking!!","If it moans, don't date it, if it limps, don't help it, if it runs, you're in trouble","Always carry a spare sock, you'd be surprised","Never trust a man who says \"I've got a plan\"","Pack light... pee often, and stay away from anything that moans","Advice? Eat the cake first"},false,false,{[4]={{t="and never trust a woman who says \"I've got it\"",afterMs=3200}},[6]={{t="you never know",afterMs=3000}}}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=careful|mood=fear",{"Advice? Get away from me... that's my advice!","Don't ask so many questions, that's all I'll say"}},
{"ASK_ADVICE","role=rescue_medical|st=friendly,neutral",{"Wash your hands, I know it sounds stupid, wash them anyway, boil water, wash again","Eat something, drink something, rest a minute, then think about running","If you bleed, press hard and keep pressing, don't peek every thirty seconds, you'll just restart it","Wash every cut with clean water, clean hands, and cover it, every single one","Sleep when you can -- a tired mind makes terrible mistakes","Go easy on yourself, grief makes you sick too, I've seen it","Never swallow a pill you can't identify, and don't mix 'em"}},
{"ASK_ADVICE","role=rescue_medical|st=careful",{"Advice from a nurse? Stay away from me, I'm exhausted"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=good,best|hour=20,5",{"Never underestimate a good night's sleep!"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=careful,neutral|rep=bad,worst",{"Advice? Change your ways!","My advice is to leave and never come back","Be better, that's all I've got","Try being decent for once","You don't listen anyway","Stay out of my way, that's my advice","Find a hole and crawl in it","Maybe think about what you've done","Do the opposite of whatever you've been doing","Advice from me? Don't make me laugh","Keep to yourself, that's what's kept me alive","Learn to say sorry -- if you can","Stop taking what isn't yours","You want advice? Get lost","Free advice: stop","Be quiet and be GONE","If I were you, I'd leave town","You'd ignore it anyway!!","Take the road less traveled, and don't come BACK","The best advice is to avoid people like you","Take a good look at yourself!!","Don't push your luck","Think twice, then think again, then do NOTHING","Advice? Stay far away from me","Don't look to me for guidance","Listen to the people you've wronged","I'm not your counselor","Do better, or don't, I don't care","Go home, wherever that is!","Maybe they were right about you","Keep your hands to yourself, and your mouth shut"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=recent_zombie_contact",{"Run! no- walk! no- hide! I'm sorry, I'm a mess","Stay quiet, stay still, stay hidden, they'll pass, maybe","Advice? Leave now -- we can talk later","Not a sound, not a move, nothing!","Breathe, slow, shallow, shallow, still","Move away from the noise -- toward the quiet","Stay down low and don't rush it","T-they follow sound, so be silent as the grave!","Quiet! That's my advice, quiet!"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=player_armed",{"Use that wisely, one at a time, aim for the head","Don't waste bullets, only shoot if you have to","Keep it clean and loaded, and quiet if you can"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral",{"Get yourself a good pair of boots","Don't carry more than you can drop in a hurry","Find one friend you'd trade a coat with","Honestly? Grab food and sleep whenever you get the chance","Learn your neighbors' faces","Always know two ways out","Keep something to look forward to","Write things down","Never leave the water for last","Trust slowly","Keep your promises, even the small ones","Don't be the hero","Sleep with your boots on","Stay clean if you can","Pick your fights, and don't pick many","Learn to be bored..","Keep your hands busy","Look people in the eye","Don't take what you can't carry","Say thank you","Cry when you need to... but cry quietly","Wear shoes with laces","Keep a candle stub in every pocket","Write your name on your arm in marker","Tie a bell on your door...","Carry a spare pair of socks in a plastic bag","Never sleep with your head by a window","Always leave the last bite","Eat slowly","Split your supplies in two places","Walk heel to toe at night","Learn one good knot","Keep one hand free -- always..","Get a dog","If you find a bed, sleep first, think later","Don't loot a house that's been cleaned out too neatly","Plant something, even if it dies","Count your bullets after every fight","Tell someone where you're going","When you're sure it's safe, wait ten more minutes","Talk to yourself in your head, not out loud","Say please and thank you"},false,false,{[1]={{t="nobody tells you your feet will outlive your good sense",afterMs=3200}},[2]={{t="a full pack kills you faster than hunger",afterMs=3500}},[3]={{t="the rest will follow, or they won't",afterMs=3500}},[4]={{t="the rest is luck",afterMs=3200}},[5]={{t="it'll matter when one of them stops being a neighbor",afterMs=3200}},[6]={{t="three if you can",afterMs=3200}},[7]={{t="a song, a story, a name, a recipe",afterMs=3500},{t="it keeps the dark off",afterMs=3000}},[8]={{t="names, dates, places",afterMs=3200},{t="you'll forget, and it'll matter",afterMs=2800}},[9]={{t="thirst makes you stupid before it makes you dead",afterMs=3500}},[10]={{t="forgive quickly, that's a balance I haven't mastered",afterMs=3200}},[11]={{t="especially now",afterMs=3500}},[12]={{t="the hero's the one who doesn't come back",afterMs=3200}},[13]={{t="you'll thank me",afterMs=3200}},[14]={{t="infection kills quieter than teeth",afterMs=3500}},[15]={{t="most of them aren't yours",afterMs=3200}},[16]={{t="boredom is safety, and safety is rare",afterMs=3500}},[17]={{t="a busy hand is a calm hand...",afterMs=3200}},[18]={{t="you can tell a lot, before they open their mouths",afterMs=3200}},[19]={{t="and don't carry what you can't use",afterMs=3500}},[20]={{t="out loud, every time",afterMs=3200},{t="it costs nothing, and it's worth everything",afterMs=2800}},[22]={{t="I know, boring",afterMs=3200},{t="but a slip-on comes off when you run, and you don't get a second try",afterMs=2800}},[23]={{t="I found out the hard way, in a cellar, in the dark, with company",afterMs=3500}},[24]={{t="it's morbid, but if you go down, somebody can tell your mama",afterMs=3200}},[25]={{t="not to keep them out -- to hear when the living come in...",afterMs=3500}},[26]={{t="wet feet will end you faster than hunger",afterMs=3200}},[27]={{t="ask me how I know",afterMs=3500},{t="actually don't",afterMs=3000}},[28]={{t="for the next person who's hungry, or for you, tomorrow",afterMs=3200}},[29]={{t="it tricks your stomach into thinking there's more",afterMs=3500}},[30]={{t="one stash goes bad, you still have the other",afterMs=3200}},[31]={{t="my daddy taught me, hunting",afterMs=3500},{t="it's quiet, it works",afterMs=3000}},[32]={{t="it'll hold a tarp, a body, or a boat",afterMs=3200}},[33]={{t="for the door, the gun, or a friend",afterMs=3500}},[34]={{t="if you can",afterMs=3200},{t="they hear it first, and they love you anyway",afterMs=2800}},[36]={{t="somebody's using it, and they'll come back",afterMs=3500}},[37]={{t="it's good for your head",afterMs=3200}},[38]={{t="not during, after",afterMs=3500},{t="during you don't have time",afterMs=3000}},[39]={{t="it's easier on whoever has to find you",afterMs=3200}},[41]={{t="I forgot that once",afterMs=3500},{t="we don't need to discuss what happened",afterMs=3000}},[42]={{t="manners are the last thing to go, and the first thing people trust",afterMs=3200}}}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly",{"You're asking the right person, I love giving advice","Sit, sit, I've got a few, and they're even useful","You'll do fine"},false,false,{[1]={{t="mostly because nobody takes it",afterMs=3000}},[3]={{t="you've got good sense, I can tell",afterMs=3200}}}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=careful",{"Advice? Here's some: go away","Get your own advice","Mind your own business!","Advice costs","Stay away from places like this","Don't talk to strangers!","I don't hand out advice","I don't give lessons for free","Here's advice - don't walk up on people, next time somebody might not bother asking questions","My advice is keep your distance from me, and from anybody else who looks like me"},false,false,{[3]={{t="and keep a distance from mine",afterMs=3000}},[4]={{t="and you can't afford it!!",afterMs=3000}},[6]={{t="like me",afterMs=3000}},[7]={{t="I hand out warnings, and you've had yours",afterMs=3000}}}},
{"ASK_ADVICE","role=civilian_loner|st=friendly,neutral",{"Move slow","Breathe through your nose","Never sleep where you cooked","Cover your tracks at a creek","Walk where the leaves are wet...","Carry salt","Check your boots every morning","Sit still for ten minutes before you move","Learn to read a track","Keep a knife on your belt and another in your boot"},false,false,{[1]={{t="a still man is a hidden man",afterMs=3200}},[2]={{t="less noise, less smell",afterMs=3500}},[3]={{t="smell carries",afterMs=3200}},[4]={{t="water keeps no secrets, but it keeps your trail",afterMs=3500}},[5]={{t="they don't crackle",afterMs=3200}},[6]={{t="it cures meat, cleans wounds, and buys friends",afterMs=3500}},[7]={{t="things crawl in",afterMs=3200}},[8]={{t="the woods settle, and tell you what's there",afterMs=3500}},[9]={{t="it's cheaper than a map",afterMs=3200}}}},
{"ASK_ADVICE","role=family_elder|st=friendly,neutral",{"Keep a clean handkerchief... dear","Eat your supper, say your prayers, and lock your door","Be kind to strangers, but not too kind","A warm blanket and a cold biscuit will get you through the worst night","Don't look back","Respect your elders"},false,false,{[1]={{t="you'd be surprised how useful",afterMs=3500}},[2]={{t="that's three rules, and they've never failed me",afterMs=3200}},[3]={{t="my mother said that... and she buried three husbands...",afterMs=3500}},[5]={{t="especially not at the kitchen",afterMs=3200}},[6]={{t="we know where the bodies are buried",afterMs=3500},{t="and I mean that literally, these days",afterMs=3000}}}},
{"ASK_ADVICE","role=family_elder|st=careful",{"I don't advise strangers"}},
{"ASK_ADVICE","role=family_youth|st=friendly,neutral",{"Don't be a hero","Learn to run","Stay with adults who know what they're doing...","Wear sneakers..","Keep a flashlight, and keep spare batteries"},false,false,{[1]={{t="heroes die first in every movie",afterMs=3200}},[2]={{t="and learn to hide, and learn to be quiet",afterMs=3500},{t="in that order",afterMs=3000}},[3]={{t="if you can find any",afterMs=3200}},[4]={{t="believe me, nobody can run in dress shoes",afterMs=3500}},[5]={{t="and keep your mouth shut",afterMs=3200}}}},
{"ASK_ADVICE","role=family_youth|st=careful",{"Advice? No"}},
{"ASK_ADVICE","role=worker|st=friendly,neutral",{"Measure twice, cut once","Have a plan, and a backup plan, and a crowbar","Check your tools every morning..","Never work alone if you can help it","Sit down and eat on your break","Wear gloves","Don't force it"},false,false,{[1]={{t="it's true for everything, even bandages",afterMs=3200}},[3]={{t="a dull blade is a dangerous blade",afterMs=3500}},[4]={{t="two sets of hands, two sets of eyes",afterMs=3200}},[5]={{t="even now, especially now",afterMs=3500}},[6]={{t="always",afterMs=3200},{t="always",afterMs=2800}},[7]={{t="if a door doesn't open, it's telling you something",afterMs=3500}}}},
{"ASK_ADVICE","role=worker|st=careful",{"Advice? Do your job!!"}},
{"ASK_ADVICE","role=family_man,family_woman|st=friendly,neutral",{"Keep a routine... even a silly one","Tell the truth, but not all of it","Feed the little ones first","Sleep in shifts","Hold them every chance you get"},false,false,{[1]={{t="kids need it, and so do we",afterMs=3500}},[2]={{t="there's a balance, and I haven't found it yet",afterMs=3200}},[3]={{t="you'll find the strength somewhere",afterMs=3500}},[4]={{t="somebody has to be awake",afterMs=3200}},[5]={{t="and let them see you smile",afterMs=3500}}}},
{"ASK_ADVICE","role=family_man,family_woman|st=careful",{"Mind your own children"}},
{"ASK_ADVICE","role=rescue_clergy|st=friendly,neutral",{"Pray, even if you don't believe it","Be kind","Confess to someone, anyone","Sleep when you can","Forgive yourself first"},false,false,{[1]={{t="it organizes your mind",afterMs=3500}},[2]={{t="it costs nothing, and it returns",afterMs=3200}},[3]={{t="a burden shared is lighter",afterMs=3500}},[4]={{t="prayer is better after rest",afterMs=3200}},[5]={{t="the rest is easier after that",afterMs=3500}}}},
{"ASK_ADVICE","role=rescue_clergy|st=careful",{"Advice for strangers costs a donation"}},
{"ASK_ADVICE","role=rescue_firefighter|st=friendly,neutral",{"Check the exits first, always","Stay low","Drink water before you're thirsty","Trust your crew","Don't go back for anything"},false,false,{[1]={{t="before you sit, before you speak",afterMs=3500}},[2]={{t="it works for smoke, and it works for bullets",afterMs=3200}},[3]={{t="I've carried men who forgot",afterMs=3500}},[4]={{t="and trust your gear more",afterMs=3200}},[5]={{t="not a coat, not a photograph",afterMs=3500},{t="not a dog",afterMs=3000}}}},
{"ASK_ADVICE","role=rescue_firefighter|st=careful",{"Leave me be"}},
{"ASK_ADVICE","role=militia|st=friendly,neutral",{"Keep your boots dry, I've seen trench foot take grown men down","Check your weapon before you need it","Never run unless you've picked where you're running to","I sleep when my shift's over and eat whatever's there... that's my whole system"},false,false,{[1]={{t="and your mouth shut",afterMs=3500}},[2]={{t="not after",afterMs=3200}}}},
{"ASK_ADVICE","role=militia|st=careful",{"On your way, friend, we don't need the company"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,3",{"Stay home, stay put, lock the doors, and wait for help","Just stay put and keep quiet, don't go making a fuss","Stock up on water now, before the taps run dry..."}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|day=4,14",{"Move if you must, stay if you can, but pick one and commit","Ration everything"},false,false,{[2]={{t="a week is nothing, a month is long",afterMs=3500}}}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|day=15,99999",{"Find a rhythm","Plant something, mend something, teach somebody something"},false,false,{[1]={{t="survival is mostly routine",afterMs=3500}}}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=22,4",{"Stay put, don't wander in the dark, you'll fall in a hole, or worse","Go to sleep, if you can, and let the night pass","If you hear something, wait, wait until it's quiet, wait until it's light","Don't go wandering tonight"},false,false,{[4]={{t="the morning's a better teacher",afterMs=3500}}}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=5,10",{"Eat something before you do anything else","Scout before you commit","Use the cool hours, the heat will come"},false,false,{[1]={{t="breakfast first",afterMs=3200}},[2]={{t="the morning's for looking",afterMs=3500}}}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=11,18",{"If you're wearing yourself out, stop for a bit. You don't have to wait till you can't take another step","Don't use up everything you have just because you found more. You might be waiting a while for the next lot"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=19,21",{"Find shelter now, not later","Light a fire only if you can hide the smoke, and you can't, so don't"},false,false,{[1]={{t="later it's a scramble",afterMs=3500}}}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|hour=16,5|mood=sad",{"Say what you need to say to the people you love"},false,false,{[1]={{t="tonight",afterMs=3500},{t="not tomorrow",afterMs=3000}}}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=fear",{"Breathe through it!","If you can't stop shaking, hold a stone"},false,false,{[1]={{t="when your heart's hammering, count your breaths, one to ten, and again",afterMs=3500}},[2]={{t="something cold, something heavy",afterMs=3200}}}},
{"ASK_ADVICE","reg=raider|st=neutral,careful",{"Advice? Don't trust anybody who smiles at you, and never turn your back, that's my whole philosophy","Keep your gun loaded, your mouth shut, and your eyes on every shadow","Smell the food, taste the water slow, and watch your friends closer than either","Take what you need and don't give any of it back, that's all I know","Move at night, hide in the day, and don't ever stay in one place more than two nights"}},
{"ASK_ADVICE","reg=raider|st=hostile",{"My advice? Run, and don't look back!"}},
{"ASK_ADVICE","reg=raider|st=friendly",{"Honestly? Find people you can count on, even one, being alone in this will eat you alive","Count your bullets every morning, it calms you down, and it keeps you honest"}},
{"ASK_ADVICE","role=raider_boss,gang_boss,biker_boss|st=neutral,careful",{"Never let 'em see you weak, and never turn your back on a man with nothing to lose"}},
{"ASK_ADVICE","reg=gang|st=neutral,careful",{"Stick with your crew, nobody survives alone","Alleys, {g:man|lady}, not main roads, and stay out of sight","Don't make deals with strangers, don't take anything you didn't earn","My grandma said, keep your friends close and your fear closer, she was right"}},
{"ASK_ADVICE","reg=gang|st=hostile",{"Advice? Stay off my block!"}},
{"ASK_ADVICE","reg=gang|st=friendly",{"Check your arms every morning, every single morning, it saved my life"}},
{"ASK_ADVICE","reg=club|st=neutral,careful",{"Keep your bike running, your gun loaded, and your brothers close","Never ride at night, and never on an empty tank, I learned that the hard way","Drink water, find food, the rest doesn't matter much"}},
{"ASK_ADVICE","reg=club|st=hostile",{"My advice? Leave, and don't come back!"}},
{"ASK_ADVICE","reg=club|st=friendly",{"Don't stop, {g:brother|sister}, the ones who stop don't last"}},
{"ASK_ADVICE","reg=crime|st=neutral,careful",{"Diversify your supplies, have an exit plan, and always keep something to trade","Hear things before you do things, that's what keeps me breathing","Don't tell somebody everything just because they asked nicely. You can answer a question without giving yourself away"}},
{"ASK_ADVICE","reg=crime|st=friendly",{"Find reliable allies, and pay them well"}},
{"ASK_ADVICE","reg=prison|st=neutral,careful",{"Stay quiet, stay small, don't draw attention, that's how I survived inside and out","Don't trust anyone, not even yourself on bad nights","Keep a weapon within reach, even when you sleep, especially when you sleep"}},
{"ASK_ADVICE","reg=prison|st=hostile",{"Advice? Don't ask me for anything!"}},
{"ASK_ADVICE","reg=prison|st=friendly",{"Breathe, just breathe, take it one hour at a time, that's all I can say"}},
{"ASK_ADVICE","reg=outlaw|st=neutral,careful",{"Learn to read the woods, they'll tell you where the danger is","No fires at night, ever - and off the road, tracks give you away","Fill every container with water whenever you can, you'll thank me later"}},
{"ASK_ADVICE","reg=outlaw|st=friendly",{"Find a quiet place, make it yours, defend it with everything you have"}},
{"ASK_ADVICE","reg=law|st=neutral,careful",{"Go home, stay inside, keep your people close","Keep a record of everything, it matters, even now","Don't take unnecessary risks, there's no hospital to patch you up","Follow the instructions of any authority you meet, it keeps order"}},
{"ASK_ADVICE","reg=law|st=hostile",{"My advice is to cooperate fully"}},
{"ASK_ADVICE","reg=law|st=friendly",{"Check on your neighbors, that's about all we can do"}},
{"ASK_ADVICE","reg=military|st=neutral,careful",{"Shut it, don't waste shit, stay low","Follow the chain of command, if there is one","Clean your weapon and know where your partner is"}},
{"ASK_ADVICE","reg=military|st=hostile",{"Follow orders, that's the only advice I have"}},
{"ASK_ADVICE","reg=military|st=friendly",{"Keep your head up, stay with the group, we'll get through this"}},
{"ASK_ADVICE","role=soldier_green|st=neutral,careful",{"Don't be like me, don't panic, don't freeze, I wish someone told me that earlier"}},
{"ASK_ADVICE","role=militia|st=neutral,careful",{"Grow what you eat, hunt what you can, and pray for the rest","Keep a strong fence, a loaded rifle, and a loyal dog"}},
{"ASK_ADVICE","role=militia|st=friendly",{"Come to our farm, friend, there's safety in numbers"}},
{"ASK_ADVICE","fact=recent_zombie_contact",{"I just saw one round here - keep looking, alright? Me talking doesn't mean it's safe","One of them was close a second ago, you can listen without looking at me","Saw one here - don't know where it went - don't assume it's gone","Wouldn't sit down yet, one of those things was pretty close","Watch round us, I saw something moving much too close for my liking","Had one of the dead moving about here, let's deal with that before we get into tomorrow","Leave yourself room, one was close by just now","Don't turn round to look at me, keep watching out there, I just saw one","I spotted one right here, work out which way you're running if it comes back","Can't give you a long answer here, there was one of them close by","Give me a bit of room, saw one nearby; don't want us tripping over each other getting out","I wouldn't start unpacking, not after what I just saw round here","Keep looking, only saw one here, but I'm not taking chances over one"}},
{"ASK_ADVICE","tmp=fresh|fact=recent_zombie_contact",{"Don't get bitten, okay? I just saw one","One was right round here - don't go looking at its face - please don't","I saw one nearby, the way its hands kept... Just don't let it reach you","Don't let it grab you, one was close, that's all I've got, I'm sorry","Can we talk somewhere else? I just saw one of those people"},false,false,{[1]={{t="God, listen to me - like that's a normal thing to say",afterMs=2400}},[5]={{t="Things, fuck, I don't know what to call them",afterMs=1600}}}},
{"ASK_ADVICE","tmp=veteran|fact=recent_zombie_contact",{"Work out how you'd leave before you decide to stay"}},
{"ASK_ADVICE","tmp=seasoned,veteran|fact=recent_zombie_contact",{"One of the dead was close - watch you don't back into that sort of tight space"}},
{"ASK_ADVICE","fact=recent_human_contact",{"Had somebody armed close by - don't know where they went - keep your head down","Someone dangerous was near us a moment ago, not a great time to stand around talking","Don't go waving somebody over because they're breathing, just had trouble with strangers here","I'd rather keep this short, hostile was close by - can't tell you they've gone","Had company close by, not friendly company - keep an eye out","Don't announce where you're headed, just spotted trouble round here","I wouldn't be yelling across here, someone hostile was nearby","Quietly, please, saw somebody armed close by and I don't want them hearing what we're doing"}},
{"ASK_ADVICE","fact=recent_human_contact|world=road",{"Had trouble here - look for somewhere to get behind, not just a road to run down"}},
{"ASK_ADVICE","tmp=veteran|fact=recent_human_contact",{"Somebody dangerous around here - where exactly? Don't know now, that's why we're being careful"}},
{"ASK_ADVICE","st=friendly,neutral,careful|fact=player_armed",{"Well, start with what's in your hand - don't point it at someone you're asking for help"}},
{"ASK_ADVICE","fact=player_armed",{"That weapon might impress somebody, might scare 'em into doing something stupid, too","Think about walking up to people holding that - how'd you take it?","If you want people to talk, don't lead with the weapon","You can still walk away - don't let holding that thing make you forget it","You've got a weapon, doesn't mean you've got to have the last word","Try not to make people feel they need a weapon because you've got one","Hold on to it, just don't start thinking nothing can touch you now"},false,{[2]="GENERIC"}},
{"ASK_ADVICE","tmp=seasoned,veteran|fact=player_armed",{"You're armed - alright, still need somewhere to go if it gets bad"}},
{"ASK_ADVICE","tmp=fresh|fact=player_armed",{"Careful with that, please, I'm jumpy enough as it is"}},
{"ASK_ADVICE","hour=21,5",{"Don't just stumble into the first dark room and sleep there - check it, even if you're exhausted","Going out tonight? Slow down a bit, you can't see what you're running into","This late, it's the stuff I can't see that bothers me - keep that in mind","Quiet out there doesn't mean there's nobody out there","Pick where you're headed before you leave cover tonight, don't work it out in the open","Remember how you got in, corners all start looking the same in the dark","Listen before you open it, especially in this dark","You don't have to go after every noise out there - nobody's grading you on being brave"}},
{"ASK_ADVICE","hour=21,5|world=door",{"I'd leave the exploring for daylight - open door doesn't mean you need to go through it"}},
{"ASK_ADVICE","hour=21,5|world=fence",{"Careful running tonight, catch a fence you didn't see and you're on your face"}},
{"ASK_ADVICE","tmp=fresh|day=0,7",{"Don't get bitten, please","I keep wanting to help them up when they fall - don't, I don't think that's helping them anymore","Watch their mouths, their fucking mouths, never thought I'd have to tell somebody that","If they look sick, don't let them hug you out of politeness - sounds awful, doesn't it - still","I'm not waiting on some brilliant idea here, I'm trying not to die - same as you","Skin away from teeth, that's my plan - fucking brilliant plan, isn't it","Don't walk up because you know the clothes, nearly did that myself","I don't know what to believe on the radio","Please don't do something stupid just so nobody sees you're scared","Don't let someone brush off a bite, I don't know what it means, but it means SOMETHING","Call out before you get close, everyone's on edge - don't want someone getting the wrong idea","Keep thinking somebody'll explain what we're supposed to do - until then... keep out of reach, I guess","Get something solid between you and them, not-- I don't mean push somebody else in the way","They can look hurt and still grab you, I've seen it - don't stop to fuss over them","Wish I had an answer, been scared to close my eyes since this started","Hands shaking? Stop somewhere they can't reach you, give yourself a second - don't just pretend you're fine","I hear moaning and nearly call back - keep having to stop myself - be careful with that","Don't get crowded in, I wouldn't know what to do once they're all round me","If you find someone you know, LOOK first - don't run straight up - please"},false,false,{[1]={{t="You wanted something useful - I know - I just... that's all I can think about",afterMs=3000}},[8]={{t="And I only heard bits of it - don't go doing something because I said it sounded alright",afterMs=2300}}}},
{"ASK_ADVICE","tmp=fresh|day=0,7|world=window",{"Look through the window before you stick your arm in - nearly forgot that myself"}},
{"ASK_ADVICE","reg=civilian,family|st=friendly,neutral",{"What am I, some fucking philosopher?"},false,false,{[1]={{t="I used to ask my wife where we kept the towels",afterMs=1900}}}},
{"ASK_ADVICE","st=friendly,neutral,careful|sex=m",{"Advice? I ate breakfast over a trash can - you sure I'm your guy?"},false,{[1]="GENERIC"}},
{"ASK_ADVICE","st=friendly,neutral,careful",{"Last smart thing I did was shut up, should've asked me then","Check the other way out now, I know you don't feel like it - do it anyway","Keep checking the place, empty when you arrived doesn't mean empty all night","Save some energy for getting out again, you'll be carrying more, probably","Don't take my word just because I sound calm, check what you can","If they tell you to back off, back off, they can be terrified and still hurt you","When somebody says no, hear the no. Saves a lot of trouble","You don't have to tell every stranger the whole truth about yourself","Take advice from me with the same care you'd take it from anybody else"}},
{"ASK_ADVICE","tmp=seasoned,veteran",{"Work with what you've got - don't plan on finding the thing you need halfway through","Work out what you can actually carry before you decide you're taking all of it","If you messed up, stop - don't keep going just so it looks like you meant to","They want you to hurry, but won't explain? Take your time - there's probably a reason","Don't keep following someone just to finish an argument, keep track of the way out","Keep your map dry, soaking paper with all the ink smeared off isn't much help","If you've got to shout for them to hear, other people can hear too - remember that","Know which bag you're letting go of if you have to - don't wait until something's pulling on it","Tell the one on watch if the plan changes, nobody tells that poor bastard anything","Save your voice, shout when you actually need somebody to hear","Look for a way out first, then start looking at what you can take"}},
{"ASK_ADVICE","st=friendly,neutral",{"Keep a bit of water handy, somewhere you don't have to empty the whole bag to get at it","If someone's rushing you into a decision, ask why they need it so fast","Don't mistake a person sounding sure for a person knowing","Ask where a story came from before you build a plan around it","You can turn back. Being embarrassed is better than being stuck","Don't promise somebody help just to make the conversation easier","If you don't understand an agreement, ask again before you agree","Let people finish. Sometimes the useful part comes after the bit that scares you"}},
{"ASK_ADVICE","tmp=seasoned,veteran|world=door",{"Don't all watch the same door, somebody take the other side"}},
{"ASK_ADVICE","reg=family,civilian,worker",{"Tell your people where you're going and when you'll be back - when to start worrying, at least"}},
{"ASK_ADVICE","reg=worker,family",{"Sort out the job while there's light, you can argue about who forgot the hammer afterward"}},
{"ASK_ADVICE","reg=family,rescue",{"Don't tell a kid there's breakfast tomorrow if you don't know you've got it"}},
{"ASK_ADVICE","reg=worker,civilian|world=fence",{"Leave some of it, you still have to get yourself over fences with that lot"}},
{"ASK_ADVICE","reg=law,military,rescue",{"Ask if they saw it themselves, not their cousin, not some fellow their cousin knows"}},
{"ASK_ADVICE","day=14,3650",{"Uniform tells you what they used to do, doesn't tell you what they're doing now"}},
{"ASK_ADVICE","reg=civilian,worker,family|world=vehicle",{"Keep that only key on you, not in the bag you keep forgetting in the car"}},
{"ASK_ADVICE","reg=worker,rescue",{"Don't pile everything useful in one room, lose that room to a fire and you're screwed"}},
{"ASK_ADVICE","st=friendly",{"When you get somewhere you can breathe a bit, take a minute"},false,false,{[1]={{t="You're gonna get things wrong, we all are - doesn't mean you're no good at this",afterMs=2700}}}},
{"ASK_ADVICE","reg=civilian,family|tmp=fresh|st=friendly,neutral",{"Don't get bitten, okay? That's all I know, and drink water - Mama would say drink water","Keep a picture of your family in your pocket, when you get scared, look at it, it helps me, anyway","I've made it this far by being quiet and being nice to people - I don't know if that'll work for you","Don't go in basements - just don't, I won't tell you why"}},
{"ASK_ADVICE","reg=civilian,family|tmp=fresh,seasoned|st=friendly,neutral|day=8,9999",{"Don't believe the radio when it says help is on the way - that's what I'd tell myself a week ago"}},
{"ASK_ADVICE","reg=civilian,family|tmp=seasoned,veteran|st=friendly,neutral",{"Stay quiet, stay fed, stay out of towns after noon - break one rule, you're still breathing, break two, maybe not"}},
{"ASK_ADVICE","reg=civilian,family|tmp=seasoned,veteran|st=friendly,neutral|world=building",{"Always know two ways out of any room you're in - always, even the bathroom","Don't loot tired, tired folks miss the one standing in the closet"}},
{"ASK_ADVICE","reg=civilian,family,worker|tmp=seasoned,veteran|st=friendly,neutral|world=door",{"Carry a pry bar, opens doors, drops the dead, and people see it and walk wide around you"}},
{"ASK_ADVICE","reg=civilian,family|tmp=seasoned,veteran|st=friendly,neutral|day=4,9999",{"Wear long sleeves, even in this heat - Denim's saved my arm twice now"}},
{"ASK_ADVICE","reg=civilian,family,worker,rescue|st=hostile",{"Leave, that's my advice"}},
{"ASK_ADVICE","reg=worker|st=friendly,neutral",{"Wear boots with steel toes, they step on your feet in a crowd, and then you're down"}},
{"ASK_ADVICE","reg=worker|st=friendly,neutral|world=door",{"Measure twice, cut once, now it's listen twice, open the door once"}},
{"ASK_ADVICE","reg=rescue|role=rescue_medical|st=friendly,neutral",{"Wash every scratch, boil the water - treat a fever like a fire - watch it, and don't sleep next to it"}},
{"ASK_ADVICE","reg=rescue|role=rescue_firefighter|st=friendly,neutral|world=door",{"Put your ear to a door before you open it - scratching, breathing, anything, you find another door"}},
{"ASK_ADVICE","reg=rescue|role=rescue_clergy|st=friendly,neutral",{"Keep a friend, the ones who go it alone don't last, and the ones who do stop being themselves"}},
{"ASK_ADVICE","reg=law,swat|st=friendly,neutral",{"Don't be a hero, {sir}, heroes were the first reports I had to write"}},
{"ASK_ADVICE","reg=law|tmp=seasoned,veteran|st=friendly,neutral",{"Keep your weapon clean, your boots dry, and your mouth shut about what you're carrying"}},
{"ASK_ADVICE","reg=law,swat|role=law_sergeant,swat_lead,law_trooper|st=friendly,neutral",{"Situational awareness - check behind you every thirty seconds, every time, till it's habit"}},
{"ASK_ADVICE","reg=law,swat|st=careful,hostile",{"My advice is you comply with what I'm telling you - step back"}},
{"ASK_ADVICE","reg=military|st=friendly,neutral",{"Hydrate, sleep in shifts, don't shoot unless you have to - everything else is details"}},
{"ASK_ADVICE","reg=military|tmp=seasoned,veteran|st=friendly,neutral",{"Don't bunch up, one of them gets one of you, it gets all of you"}},
{"ASK_ADVICE","reg=elite",{"Move quiet, rest in cover, and stay away from people, us included"}},
{"ASK_ADVICE","reg=military|st=careful,hostile",{"Advice: leave this position immediately"}},
{"ASK_ADVICE","reg=outlaw,raider|st=friendly,neutral",{"Always get the other guy's gun first, works on the living too"}},
{"ASK_ADVICE","reg=crime|st=friendly,neutral",{"Everything's for sale - everything - remember that and you'll do fine"}},
{"ASK_ADVICE","reg=prison|st=friendly,neutral",{"Never let anybody see you scared, out here's just the yard, only bigger"}},
{"ASK_ADVICE","reg=gang|st=friendly,neutral",{"Pick a side, {g:man|lady} - Loners get eaten, by them, or by us"}},
{"ASK_ADVICE","reg=club|st=friendly,neutral",{"Keep your tank full and don't pull over for anybody - anybody"}},
{"ASK_ADVICE","reg=outlaw,raider,gang,club,crime,prison|st=hostile",{"Stop asking strangers for advice, you're doing it right now - see how that's working out?"},false,{[1]="GENERIC"}},
{"ASK_ADVICE","reg=outlaw,raider,gang,club,crime,prison|st=careful,hostile",{"Walk away slow, that one's free - everything else costs"}},
{"ASK_ADVICE","reg=civilian,worker,family|tmp=seasoned|st=neutral,friendly",{"You want it straight? It ain't comfortable and most folks don't care for it"},false,{[1]="ASK_ADVICE"}},
{"ASK_ADVICE","role=soldier_nco,elite_delta,law_sheriff|tmp=veteran|st=neutral",{"I've got one piece of advice and nobody likes it - you want to hear it anyway?"},false,{[1]="ASK_ADVICE"}},
{"ASK_ADVICE","reg=club,crime,outlaw|st=neutral",{"Advice - huh, you willing to hear something about yourself?"},false,{[1]="ASK_ADVICE"}},
{"ASK_AGE","reg=civilian,family,worker,rescue|st=friendly,neutral",{"Thirty-four, though lately I feel eighty, and sometimes twelve","Forty-one... I think, forty-two next month, if there IS a next month","Old enough to know better, young enough to still try","Twenty-six... I was supposed to get married in September","Seventeen, don't tell my mom, I told her I was eighteen so she'd let me go","Fifty-three, and I've never felt it more than today","Sixty-two, and my knees are asking if we can stop now","Almost thirty, I had a whole plan for thirty","Twenty-two, I just graduated, I was going to be a nurse, I'm a nurse, I guess, just without the hospital","Forty-eight, which is old enough to be tired, and too young to quit","Seventy-eight, and I'm not done yet, don't count me out","Nineteen, and I feel like I've lived a hundred years since Friday...","Thirty-eight","Twenty-three","Old enough to know a lot of things I wish I didn't","Fifty-two","Nineteen","Forty-four","Sixty-seven"},false,false,{[13]={{t="but I feel eighty-eight",afterMs=3200},{t="some days, a hundred",afterMs=2800}},[14]={{t="I was going to turn twenty-four in August",afterMs=3500}},[15]={{t="And young enough to keep going anyway",afterMs=3200}},[16]={{t="my knees say sixty",afterMs=3500},{t="my heart says thirty",afterMs=3000}},[17]={{t="I've been grown for about a week",afterMs=3200}},[18]={{t="middle-aged, middle of nowhere, middle of the end",afterMs=3500}},[19]={{t="retired, tired, and inspired",afterMs=3200}}}},
{"ASK_AGE","reg=civilian,family,worker,rescue|st=careful",{"That's rude to ask a lady","My age is my business","Why?","Old enough to shoot straight, that's all you need to know about me"}},
{"ASK_AGE","role=rescue_medical|st=friendly,neutral",{"Thirty-six, and I've aged ten years in ten days, ask me again tomorrow, I'll be forty-six"}},
{"ASK_AGE","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=funny",{"Old enough to remember when the world made sense","Ask me tomorrow, I'll be a day older"}},
{"ASK_AGE","reg=raider|st=neutral,careful",{"Old enough to know better, young enough to not give a shit","Twenty-six, why, you thinking I'm too young for this?","How old? Old enough to put you in the ground","Thirty-three, and it feels like ninety these days","Does it matter? Age doesn't mean anything out here"}},
{"ASK_AGE","reg=raider|st=hostile",{"Old enough to kill you, that's how old"}},
{"ASK_AGE","reg=raider|st=friendly",{"Thirty-one, you? You look like you've had a rough week"}},
{"ASK_AGE","reg=gang|st=neutral,careful",{"Nineteen, but I've lived like a man since I was twelve","Old enough to run things, that's how old","Twenty, why? You think I'm a kid?"}},
{"ASK_AGE","reg=gang|st=hostile",{"Mind your own damn business"}},
{"ASK_AGE","reg=club|st=neutral,careful",{"Forty-four, and the knees feel every year","Old enough to remember when this was a quiet county","Fifty-one, and I've buried a lot more people since last week"}},
{"ASK_AGE","reg=club|st=hostile",{"Old enough to know better than to answer you"}},
{"ASK_AGE","reg=club|st=friendly",{"Thirty-eight, ask my back how it feels"}},
{"ASK_AGE","reg=crime|st=neutral,careful",{"That is a personal question","Old enough to be careful","Forty, give or take"}},
{"ASK_AGE","reg=crime|st=friendly",{"Thirty-five, and I've got the knees to prove it"}},
{"ASK_AGE","reg=prison|st=neutral,careful",{"Twenty-nine, but it felt like a hundred in there","Thirty-four, I think, I lost count"}},
{"ASK_AGE","reg=prison|st=hostile",{"Why?! Why do you wanna know?!"}},
{"ASK_AGE","reg=prison|st=friendly",{"Twenty-seven, I was supposed to get out at thirty"}},
{"ASK_AGE","reg=outlaw|st=neutral,careful",{"Forty, forty-one, I stopped counting birthdays a while ago","Old enough to know how to survive, young enough to do it"}},
{"ASK_AGE","reg=outlaw|st=friendly",{"Pushing fifty, and still standing, can you believe it?"}},
{"ASK_AGE","role=deserter|st=neutral,careful",{"Twenty-two, and I feel eighty"}},
{"ASK_AGE","reg=law|st=neutral,careful",{"Forty-two, why do you ask?"}},
{"ASK_AGE","reg=law|st=hostile",{"That is not relevant"}},
{"ASK_AGE","reg=law|st=friendly",{"Thirty-nine, still got a few good years in me"}},
{"ASK_AGE","role=law_sheriff|st=neutral,careful",{"Fifty-eight, and tired"}},
{"ASK_AGE","reg=military|st=neutral,careful",{"Twenty-eight, almost done with my enlistment"}},
{"ASK_AGE","reg=military|st=friendly",{"Twenty-one, my mom'd kill me if she knew I was here"}},
{"ASK_AGE","role=soldier_green|st=neutral,careful",{"Nineteen... I'm only nineteen, I shouldn't be here","Um, twenty? I think I'm twenty"}},
{"ASK_AGE","reg=elite|st=neutral,careful",{"Not your concern, move along"}},
{"ASK_AGE","role=militia|st=neutral,careful",{"Fifty-three, which is old enough to know exactly what I'm doing","Forty-six, with a bad shoulder"}},
{"ASK_AGE","reg=civilian,family|tmp=fresh|st=friendly,neutral",{"Twenty-three, turned twenty-three on the eighth - had a cake from the grocery with my name spelled wrong","Old enough to know better than to be out here - young enough I don't know what else to do","Thirty-one, my mother still sends me a card with five dollars in it every year - sent, she sent me one"}},
{"ASK_AGE","reg=civilian,family|role=family_man,civilian_man|tmp=fresh|st=friendly,neutral",{"Thirty-nine, forty in September, if there's a September - my wife was planning a party, she'd already bought the hats"}},
{"ASK_AGE","reg=family|role=family_youth|tmp=fresh|st=friendly,neutral",{"I'm seventeen - please don't tell me I'm old enough, everybody keeps telling me I'm old enough"}},
{"ASK_AGE","reg=civilian,family|role=family_elder|tmp=seasoned|st=friendly,neutral",{"Sixty-eight, buried a wife, a war and two good dogs - figured I'd seen the worst of it - figured wrong"}},
{"ASK_AGE","reg=civilian,family|tmp=seasoned|st=friendly,neutral",{"Forty-one, I think, quit counting days, so I might be forty-two by now and nobody sang"}},
{"ASK_AGE","reg=civilian,family,worker,rescue|st=hostile",{"Why, you figuring whether you can take me? Try it"}},
{"ASK_AGE","reg=rescue|role=rescue_firefighter|st=friendly,neutral",{"Thirty years on the fire department, do the math, my knees'll tell you I'm a hundred"}},
{"ASK_AGE","reg=rescue|st=friendly,neutral",{"Old enough to have held a lot of hands at the end - young enough to keep doing it a while yet"}},
{"ASK_AGE","reg=worker|st=friendly,neutral",{"Fifty-two, thirty years of it at the distillery, they always said the angels took their share, took everybody's now"}},
{"ASK_AGE","reg=law,swat|st=friendly,neutral",{"Forty-four, twenty-one years with the department, was going to put in my papers at twenty-five","Old enough to remember when this badge meant something to folks - that was two weeks ago"}},
{"ASK_AGE","reg=law,swat|st=careful,hostile",{"My age isn't the subject, your hands are - keep them visible"}},
{"ASK_AGE","reg=military|tmp=fresh|st=friendly,neutral",{"Eighteen, nineteen in October - I enlisted for the college money"}},
{"ASK_AGE","reg=military,elite|tmp=seasoned,veteran|st=friendly,neutral",{"Thirty-six, old for the job, young for the rank, neither one matters much out here"}},
{"ASK_AGE","reg=elite|st=friendly,neutral",{"Old enough"}},
{"ASK_AGE","reg=military,elite|st=careful,hostile",{"Doesn't concern you - give us some space"}},
{"ASK_AGE","reg=outlaw,crime|st=friendly,neutral",{"Thirty-some, had a birthday in county lockup once, fellas made me a cake out of honey buns - best one I ever had","Twenty-nine, spent most of it being told I wouldn't see thirty - starting to think they were onto something"}},
{"ASK_AGE","reg=raider,gang,club,prison|st=friendly,neutral",{"Old enough to have done time, young enough to do it again - not that anybody's left to lock me up","What's it to you? You counting how long I got left? Longer than you, bet on it"}},
{"ASK_AGE","reg=outlaw,raider,gang,club,crime,prison|st=careful",{"Old enough to know strangers asking cute questions usually want something"}},
{"ASK_AGE","reg=outlaw,raider,gang,club,crime,prison|st=hostile",{"Older than you're gonna get if you don't shut up and move"}},
{"ASK_AGE","reg=civilian|tmp=fresh|st=friendly,neutral",{"Twenty-six, I keep thinking that's too young for this, then I look around"}},
{"ASK_AGE","reg=family|st=neutral,friendly",{"Thirty-eight, feels like sixty since the fourth"}},
{"ASK_AGE","reg=worker|tmp=seasoned|st=neutral",{"Fifty-one, working since I was fifteen, so call it seventy in the joints"}},
{"ASK_AGE","role=rescue_medical|st=neutral",{"Twenty-nine - Aged out of a nursing shift and into whatever this is"}},
{"ASK_AGE","role=rescue_clergy|st=friendly,neutral",{"Sixty-four, preached forty of 'em, never had a month like this one"}},
{"ASK_AGE","role=rescue_firefighter|st=neutral",{"Forty-three, twenty on the job, both those numbers feel made up now"}},
{"ASK_AGE","reg=civilian|tmp=seasoned|st=neutral",{"Old enough to remember when a siren meant a tornado"}},
{"ASK_AGE","role=family_elder|st=neutral,friendly",{"Eighty-one in November, if there's a November"}},
{"ASK_AGE","role=law_deputy|st=neutral",{"Twenty-four, I got this badge in March - March!"}},
{"ASK_AGE","role=law_sheriff|st=neutral|mood=sad",{"Sixty-two, I was going to retire in the spring and buy a bass boat"}},
{"ASK_AGE","role=soldier_nco|tmp=veteran|st=neutral",{"Thirty-six, half of it in green - wouldn't know how to do anything else now"}},
{"ASK_AGE","role=soldier_green|tmp=fresh|st=neutral",{"Nineteen, twenty in October, I keep saying that like it's a plan"}},
{"ASK_AGE","reg=elite|tmp=veteran|st=neutral,careful",{"Old enough, and that's all you're getting"}},
{"ASK_AGE","reg=club|st=neutral",{"Forty-seven, riding since I was thirteen, broke both collarbones doing it"}},
{"ASK_AGE","reg=prison|tmp=predator|st=hostile,neutral",{"Thirty-one, nine of 'em in a state facility - you do the rest of the arithmetic"}},
{"ASK_AGE","reg=civilian|tmp=fresh|st=hostile",{"Why does that matter? Does any of it matter? Nothing matters, so"}},
}
